import {clockState,advance,seek,reset,parameterValue} from './runtime-core.mjs';
const {config,render}=await import(new URL('./scene.mjs',location.href).href);
const $=s=>document.querySelector(s),canvas=$('#scene'),ctx=canvas.getContext('2d'),media=matchMedia('(prefers-reduced-motion: reduce)');let state=clockState(config.duration,media.matches),value=config.parameter.value,previous=performance.now();
if(media.matches)state.t=Math.min(5,config.duration);
document.title=config.title+' · 造物案例馆';$('#title').textContent=config.title;$('#subtitle').textContent=config.subtitle;$('#description').textContent=config.description;document.documentElement.style.setProperty('--accent',config.accent);canvas.setAttribute('aria-label',config.title+'的程序绘制画面。'+config.description);$('#parameter-label').textContent=config.parameter.label;let input=$('#parameter');Object.assign(input,{min:config.parameter.min,max:config.parameter.max,step:config.parameter.step,value});$('#seek').max=config.duration;$('#duration').textContent=config.duration+' 秒循环';
function labels(){ $('#play').textContent=state.playing?'暂停':'播放';$('#play').setAttribute('aria-pressed',String(state.playing));$('#seek').value=state.t;$('#time').textContent=state.t.toFixed(1)+' 秒';$('#parameter-value').textContent=value+(config.parameter.unit||'');$('#motion-note').textContent=media.matches?'已按系统设置减少动态，可手动播放。':'可暂停、逐帧拖动，或调整一个参数。';}
function draw(){ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);render(ctx,{t:state.t,value,width:canvas.width,height:canvas.height});ctx.restore();canvas.dataset.time=state.t.toFixed(4);canvas.dataset.value=value;canvas.dataset.playing=state.playing;labels()}
$('#play').onclick=()=>{state.playing=!state.playing;previous=performance.now();draw()};$('#reset').onclick=()=>{state=reset(state);value=config.parameter.value;input.value=value;previous=performance.now();draw()};$('#seek').oninput=e=>{state=seek(state,+e.target.value);draw()};input.oninput=e=>{value=parameterValue(+e.target.value,config.parameter);draw()};media.addEventListener('change',e=>{if(e.matches)state.playing=false;draw()});document.addEventListener('visibilitychange',()=>{previous=performance.now()});function frame(now){let delta=(now-previous)/1000;previous=now;if(state.playing&&!document.hidden){state=advance(state,Math.min(delta,.1));draw()}requestAnimationFrame(frame)}draw();requestAnimationFrame(frame);
